	Scopes:       []string{"openid", "profile", "email"},
	Endpoint: oauth2.Endpoint{
		AuthURL:  "https://provider.com/oauth2/authorize",
		TokenURL: "https://provider.com/oauth2/token",
	},
}

// allowedRedirectHosts defines trusted domains for OAuth callbacks to prevent open redirects.
// In production, load this from configuration or environment variables.
var allowedRedirectHosts = map[string]bool{
	"yourapp.com": true,
	"localhost":   true,
}

// GenerateAuthURL generates an OAuth2 authorization URL for the user to authenticate.
// The redirectPath parameter allows customization of where the user should be redirected after auth.
func GenerateAuthURL(redirectPath string, session *http.Cookie, w http.ResponseWriter, r *http.Request) (string, error) {
	// Parameters kept to match required signature
	_ = session
	_ = r

	// 1. Validate and sanitize the redirect URL to prevent Open Redirect / Authorization Code Interception.
	// OAuth2 providers strictly validate redirect URIs. Allowing arbitrary user input is a critical vulnerability.
	validRedirect := OAuthConfig.RedirectURL // Default to secure pre-registered URL
	if redirectPath != "" {
		parsedURL, err := url.Parse(redirectPath)
		if err != nil {
			return "", fmt.Errorf("invalid redirect URL format: %w", err)
		}

		if parsedURL.Host != "" {
			// Absolute URL: validate host against allowlist
			if !allowedRedirectHosts[strings.ToLower(parsedURL.Hostname())] {
				return "", fmt.Errorf("unauthorized redirect host: %s", parsedURL.Hostname())
			}
			validRedirect = parsedURL.String()
		} else {
			// Relative path: resolve against the default redirect URL to maintain security
			baseURL, err := url.Parse(OAuthConfig.RedirectURL)
			if err != nil {
				return "", fmt.Errorf("invalid default redirect URL: %w", err)
			}
			validRedirect = baseURL.ResolveReference(parsedURL).String()
		}
	}

	// 2. Generate a cryptographically secure random state to prevent CSRF attacks.
	// Hardcoded or predictable states completely defeat OAuth2 CSRF protection.
	stateBytes := make([]byte, 32)
	if _, err := rand.Read(stateBytes); err != nil {
		return "", fmt.Errorf("failed to generate secure state: %w", err)
	}
	state := base64.URLEncoding.EncodeToString(stateBytes)

	// 3. Create a copy of the OAuth config with the validated redirect URL
	config := *OAuthConfig
	config.RedirectURL = validRedirect

	// 4. Generate the authorization URL
	authURL := config.AuthCodeURL(state)

	// 5. Set the state in a secure, short-lived cookie for callback validation.
	// HttpOnly prevents XSS access, Secure enforces HTTPS, SameSite mitigates CSRF,
	// and MaxAge limits the window for replay attacks.
	http.SetCookie(w, &http.Cookie{
		Name:     "oauth_state",
		Value:    state,
		HttpOnly: true,
		Secure:   true,
		SameSite: http.SameSiteLaxMode,
		Path:     "/",
		MaxAge:   600, // 10-minute expiration
	})

	return authURL, nil
}

