import (
	"crypto/rand"
	"encoding/base64"
	"errors"
	"net/http"
	"net/url"
	"path"

	"golang.org/x/oauth2"
)

var OAuthConfig = &oauth2.Config{
	ClientID:     "your-client-id",
	ClientSecret: "your-client-secret",
	RedirectURL:  "https://yourapp.com/callback",
	Scopes:       []string{"openid", "profile", "email"},
	Endpoint: oauth2.Endpoint{
		AuthURL:  "https://provider.com/oauth2/authorize",
		TokenURL: "https://provider.com/oauth2/token",
	},
}

// GenerateAuthURL generates an OAuth2 authorization URL for the user to authenticate.
// The redirectPath parameter allows customization of where the user should be redirected after auth.
func GenerateAuthURL(redirectPath string, session *http.Cookie, w http.ResponseWriter, r *http.Request) (string, error) {
	// 1. Validate redirectPath to prevent Open Redirect vulnerabilities.
	// It must be a relative path without a scheme or host.
	parsed, err := url.Parse(redirectPath)
	if err != nil || parsed.Scheme != "" || parsed.Host != "" {
		return "", errors.New("invalid redirect path: must be a relative path")
	}

	// Clean the path to prevent directory traversal attacks
	cleanPath := path.Clean(parsed.Path)
	if cleanPath == "." || cleanPath == "" {
		cleanPath = "/"
	}

	// Construct the full redirect URL safely using the trusted base from OAuthConfig
	baseURL, err := url.Parse(OAuthConfig.RedirectURL)
	if err != nil {
		return "", errors.New("invalid base redirect URL in OAuth config")
	}
	baseURL.Path = cleanPath
	safeRedirectURL := baseURL.String()

	// 2. Generate a cryptographically secure random state to prevent CSRF attacks.
	// Hardcoded states are a critical security flaw in OAuth2 flows.
	stateBytes := make([]byte, 32)
	if _, err := rand.Read(stateBytes); err != nil {
		return "", err
	}
	state := base64.URLEncoding.EncodeToString(stateBytes)

	// Create a copy of the OAuth config with the validated redirect URL
	config := *OAuthConfig
	config.RedirectURL = safeRedirectURL

	// Generate the authorization URL
	authURL := config.AuthCodeURL(state)

	// 3. Set the state in a secure cookie for later validation during the callback.
	// Added MaxAge to limit the authorization window and scoped Path to the callback endpoint.
	http.SetCookie(w, &http.Cookie{
		Name:     "oauth_state",
		Value:    state,
		HttpOnly: true,
		Secure:   true,
		SameSite: http.SameSiteLaxMode,
		Path:     cleanPath,
		MaxAge:   600, // 10 minutes expiration
	})

	return authURL, nil
}

